#!/bin/bash
# Destructive integration test: run as root ONLY in a fresh, disposable OS guest.
# Uses real distro package managers and a disposable PostgreSQL cluster.
set -euo pipefail
# Test helpers also run the packaged interpreter as root. Do not leave root's
# generated bytecode in the otherwise immutable application tree after removal.
export PYTHONDONTWRITEBYTECODE=1
kind=${1:?usage: smoke-test.sh deb|apk PACKAGE [UPGRADE_PACKAGE]}
package=$(realpath "${2:?missing package}")
upgrade=$(realpath "${3:-$package}")
[ "$(id -u)" = 0 ] || { echo 'Run in a disposable root guest' >&2; exit 1; }
[ ! -e /etc/initiative/server.env ] || { echo 'Refusing an existing Initiative installation' >&2; exit 1; }
work=$(mktemp -d)
server_pid=
pg_bin=
cleanup() {
    if [ -n "$server_pid" ]; then kill "$server_pid" 2>/dev/null || true; wait "$server_pid" 2>/dev/null || true; fi
    if [ -n "$pg_bin" ] && [ -d "$work/pg" ]; then
        su -s /bin/sh -c "'$pg_bin/pg_ctl' -D '$work/pg' -m immediate stop" postgres >/dev/null 2>&1 || true
    fi
    rm -rf "$work"
}
trap cleanup EXIT
case "$kind" in
    deb)
        export DEBIAN_FRONTEND=noninteractive
        # Prevent Debian's PostgreSQL fixture package from starting a host cluster.
        [ ! -e /usr/sbin/policy-rc.d ] || cp /usr/sbin/policy-rc.d "$work/policy-rc.d"
        printf '#!/bin/sh\nexit 101\n' >/usr/sbin/policy-rc.d
        chmod 755 /usr/sbin/policy-rc.d
        apt-get update
        apt-get install -y --no-install-recommends postgresql-17 postgresql-contrib ca-certificates
        if [ -e "$work/policy-rc.d" ]; then cp "$work/policy-rc.d" /usr/sbin/policy-rc.d; else rm /usr/sbin/policy-rc.d; fi
        apt-get install -y --no-install-recommends "$package"
        pg_bin=/usr/lib/postgresql/17/bin
        ;;
    apk)
        if [ -n "${APK_TRUSTED_KEY:-}" ]; then
            install -m 644 "$APK_TRUSTED_KEY" /etc/apk/keys/initiative-server.rsa.pub
        fi
        apk add postgresql17 postgresql17-client postgresql17-contrib ca-certificates
        # Signature verification remains enabled; tests supply a trusted test key.
        apk add "$package"
        pg_bin=$(dirname "$(command -v initdb)")
        ;;
    *) echo 'Expected deb or apk' >&2; exit 1 ;;
esac
[ "$(id -u initiative)" -ne 0 ]
[ "$(stat -c %U /usr/lib/initiative)" = root ]
[ "$(stat -c %U /var/lib/initiative)" = root ]
[ "$(stat -c %G /var/lib/initiative)" = initiative ]
[ "$(stat -c %a /var/lib/initiative)" = 750 ]
[ "$(stat -c %U /var/lib/initiative/uploads)" = initiative ]
[ "$(stat -c %a /etc/initiative/server.env)" = 640 ]
[ ! -e /run/initiative-server.pid ]
# Validate the installed payload and binary modules, including the native editor
# subprocess and Typst source build on musl. All commands run as the service user.
su -s /bin/sh -c 'cd /usr/lib/initiative && if [ -f ALPINE_RUNTIME ]; then export LD_PRELOAD=/lib/libgcompat.so.0; fi; .venv/bin/python -' initiative <<'PY'
import importlib
from pathlib import Path
import sys
import typst
for module in ("asyncpg", "argon2", "cryptography", "lxml.etree", "magic", "PIL.Image", "pglast", "pycrdt", "uvicorn"):
    importlib.import_module(module)
import magic
assert magic.from_buffer(b"hello world", mime=True) == "text/plain"
assert sys.prefix == "/usr/lib/initiative/.venv", sys.prefix
assert not Path(".venv/bin/pip").exists()
assert Path("static/index.html").is_file()
assert Path("editor/editor.js").is_file()
assert Path("ota/statement.sig").is_file()
assert typst.compile(b"Native package smoke test").startswith(b"%PDF")
# Use the real editor service, which starts its own worker via sys.executable.
from app.services import editor_engine
try:
    import asyncio
    state = asyncio.run(editor_engine.bootstrap(None))
    assert state
    assert asyncio.run(editor_engine.render(state))
finally:
    editor_engine.shutdown()
PY
# Create the isolated PostgreSQL fixture with no trust listener on the network.
chmod 755 "$work"
install -d -o postgres -g postgres -m 700 "$work/pg" "$work/socket"
su -s /bin/sh -c "'$pg_bin/initdb' -D '$work/pg' --auth-local=trust --auth-host=reject" postgres >"$work/initdb.log"
su -s /bin/sh -c "'$pg_bin/pg_ctl' -D '$work/pg' -l '$work/pg/server.log' -o '-k $work/socket -h \"\"' -w start" postgres
# This is a disposable test fixture, never an installation/upgrade hook. The
# application gets its own database owner and can provision its RLS logins.
su -s /bin/sh -c "'$pg_bin/psql' -h '$work/socket' -d postgres -v ON_ERROR_STOP=1 -c 'CREATE ROLE initiative LOGIN SUPERUSER;' -c 'CREATE DATABASE initiative OWNER initiative;'" postgres
python=/usr/lib/initiative/.venv/bin/python
secret=$($python -c 'import secrets; print(secrets.token_hex(32))')
cat >/etc/initiative/server.env <<ENV
SECRET_KEY=$secret
DATABASE_URL=postgresql+asyncpg://initiative@/initiative?host=$work/socket
APP_URL=http://127.0.0.1:8173
INITIATIVE_HOST=127.0.0.1
INITIATIVE_PORT=8173
BEHIND_PROXY=false
UPLOADS_DIR=/var/lib/initiative/uploads
ENABLE_PUBLIC_REGISTRATION=true
HIBP_CHECK_ENABLED=false
# Preserve custom configuration through package upgrade.
SMOKE_CUSTOM_VALUE=retained
ENV
unset secret
chmod 640 /etc/initiative/server.env
chown root:initiative /etc/initiative/server.env
# Permit the initiative login through the temporary socket directory.
chmod 755 "$work/socket"
# A shell-looking dotenv value is data; the launcher must never execute it.
printf "SMOKE_SHELL_LITERAL=\$(touch /var/lib/initiative/uploads/env-was-executed)\n" >>/etc/initiative/server.env
start_server() {
    "$python" -c 'import os, pwd; account = pwd.getpwnam("initiative"); os.initgroups(account.pw_name, account.pw_gid); os.setgid(account.pw_gid); os.setuid(account.pw_uid); os.environ["HOME"] = account.pw_dir; os.execv("/usr/bin/initiative-server", ["/usr/bin/initiative-server"])' >"$work/application.log" 2>&1 &
    server_pid=$!
    for _attempt in $(seq 1 120); do
        if "$python" -c 'import json, urllib.request; assert json.load(urllib.request.urlopen("http://127.0.0.1:8173/api/v1/readyz", timeout=5))["status"] == "ok"' >/dev/null 2>&1; then return; fi
        if ! kill -0 "$server_pid" 2>/dev/null; then cat "$work/application.log"; return 1; fi
        sleep 1
    done
    cat "$work/application.log"
    echo 'Server did not become ready' >&2
    return 1
}
stop_server() {
    kill "$server_pid"
    wait "$server_pid" || true
    server_pid=
}
runtime_check() {
    TEST_STATE_FILE="$work/api-state.json" "$python" - <<'PYTEST'
import json
import os
from pathlib import Path
import secrets
import httpx2
state_file = Path(os.environ["TEST_STATE_FILE"])
client = httpx2.Client(base_url="http://127.0.0.1:8173/api/v1", timeout=60)
def call(method, path, **kwargs):
    response = client.request(method, path, **kwargs)
    response.raise_for_status()
    return response.json()
assert call("GET", "/version")["version"] == Path("/usr/lib/initiative/VERSION").read_text().strip()
ready = call("GET", "/readyz")
assert ready["status"] == "ok", ready
assert all(value == "ok" for value in ready["checks"].values()), ready
if state_file.exists():
    state = json.loads(state_file.read_text())
else:
    state = {"email": "native-package-test@example.com", "password": secrets.token_urlsafe(32)}
    call("POST", "/auth/register", json={**state, "username": "nativepackagetest"})
login = call("POST", "/auth/token", data={"username": state["email"], "password": state["password"]})
client.headers["Authorization"] = "Bearer " + login["access_token"]
if "community_id" not in state:
    state["community_id"] = call("POST", "/communities/", json={"name": "Native package validation"})["id"]
prefix = f"/c/{state['community_id']}"
if "task_id" not in state:
    initiative = call("POST", prefix + "/initiatives/", json={"name": "Native packaging"})
    project = call("POST", prefix + "/projects/", json={"name": "Upgrade smoke", "initiative_id": initiative["id"]})
    task = call("POST", prefix + "/tasks/", json={"title": "Preserve native upgrade data", "project_id": project["id"]})
    state["task_id"] = task["id"]
assert call("GET", prefix + f"/tasks/{state['task_id']}")["title"] == "Preserve native upgrade data"
manifest = call("GET", "/native/bundle/manifest")
assert manifest["signature"] and manifest["statement"]
assert json.loads(manifest["statement"])["version"].startswith(call("GET", "/version")["version"])
# Keep random fixture credentials private, never print them.
state_file.touch(mode=0o600, exist_ok=True)
state_file.write_text(json.dumps(state))
assert httpx2.get("http://127.0.0.1:8173/", timeout=5).status_code == 200
PYTEST
}
start_server
runtime_check
[ ! -e /var/lib/initiative/uploads/env-was-executed ]
stop_server
printf 'preserved upload\n' >/var/lib/initiative/uploads/smoke.txt
cp /etc/initiative/server.env "$work/config-before"
case "$kind" in
    deb) apt-get install -y --no-install-recommends "$upgrade" ;;
    apk) apk add --upgrade "$upgrade" ;;
esac
cmp "$work/config-before" /etc/initiative/server.env
[ "$(stat -c %U /var/lib/initiative)" = root ]
[ "$(stat -c %a /var/lib/initiative)" = 750 ]
start_server
runtime_check
stop_server
case "$kind" in
    deb) dpkg --remove initiative-server ;;
    apk) apk del initiative-server ;;
esac
cmp "$work/config-before" /etc/initiative/server.env
[ "$(cat /var/lib/initiative/uploads/smoke.txt)" = 'preserved upload' ]
[ ! -e /usr/lib/initiative/app/main.py ]
[ ! -e /run/initiative-server.pid ]
# Removal/purge do not erase uploads, logs, DB or their stable system identity.
if [ "$kind" = deb ]; then dpkg --purge initiative-server; fi
[ -d /var/lib/initiative/uploads ]
[ "$(cat /var/lib/initiative/uploads/smoke.txt)" = 'preserved upload' ]
id initiative >/dev/null
printf '%s\n' 'Native package install, runtime, upgrade and removal checks passed.'
